import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);int n = Integer.parseInt(br.readLine());long[] v = new long[n + 1];long[] u = new long[n + 1];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 1; i <= n; i++) {long val = Long.parseLong(st.nextToken());v[i] = val;u[i] = val;}Arrays.sort(u);long[] prefV = new long[n + 1];long[] prefU = new long[n + 1];for (int i = 1; i <= n; i++) {prefV[i] = prefV[i - 1] + v[i];prefU[i] = prefU[i - 1] + u[i];}int m = Integer.parseInt(br.readLine());for (int i = 0; i < m; i++) {st = new StringTokenizer(br.readLine());int type = Integer.parseInt(st.nextToken());int l = Integer.parseInt(st.nextToken());int r = Integer.parseInt(st.nextToken());if (type == 1) {out.println(prefV[r] - prefV[l - 1]);} else {out.println(prefU[r] - prefU[l - 1]);}}out.flush();out.close();}}